####### # Setup #######
($m,$h,$k) = random_subset(3,2..9); Context()->noreduce('(-x)-y','(-x)+y'); $f = Formula("$m(x-$h)+$k")->reduce; Context("Point"); Context()->parens->set("[" => {type => "Interval", close => "]"}); Context()->parens->set("{" => {type => "Set", close => "}"}); Context()->parens->set("<" => {type => "Vector", close => ">"}); $p = Point("($h,$k)");
###### # Body ######
BEGIN_PGML [`y=[$f]`]
[@KeyboardInstructions('Enter the slope here.')@]**
[_]{$m}{5}
[@KeyboardInstructions('Enter the point here.')@]**
[_]{$p}{5}
END_PGML
########## # Solution ##########
BEGIN_PGML_SOLUTION This line is in point-slope form, so we can just recognize that the slope is [`[$m]`] and the line passes through the point [`[$p]\text{.}`]
END_PGML_SOLUTION
